mapper.select:
select reg.gender,reg.post_code,dict.*,reg.name from yh_life_habit_person_dict dict,yh_user_reginfo reg
where  dict.user_code=reg.user_code and dict.habit_id=#{habitId,jdbcType=INTEGER}   
order by dict.total_day desc,dict.increase_date asc limit 0,10;

  	SELECT * FROM(
SELECT (@rowNO := @rowNo+1) AS rowno,a.* FROM (
	   select reg.gender,reg.post_code,dict.*,reg.name from yh_life_habit_person_dict dict,yh_user_reginfo reg
  	where  dict.user_code=reg.user_code and dict.habit_id=#{habitId,jdbcType=INTEGER}   
  	order by dict.total_day desc,dict.increase_date asc
	) a ,(SELECT @rowNO :=0) b where a.habit_id=#{habitId,jdbcType=INTEGER} ORDER BY a.total_day DESC 
     ) asd WHERE asd.user_code=#{userCode,jdbcType=VARCHAR}

	select person.*,dict.habit_name,dict.habitDesc,dict.life_img from  
	yh_life_habit_person_dict person,yh_life_habit_dict dict 
	where person.habit_id=dict.id 
	and person.user_code=#{userCode,jdbcType=VARCHAR}
	and person.accomplish_type=3
	and ( date(person.begin_time)<=#{increaseDate}
	and date(person.finish_tim)>=#{increaseDate}
	or  person.begin_time is null )
	and date(person.increase_date)<=#{increaseDate}

      and dict.remind_time is null
